package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IntervalSecondsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property interval seconds of observed probe ")
  void test_interval_seconds_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> IntervalSecondsVO.tryFrom(null));
    Assertions.assertEquals(1, IntervalSecondsVO.from(1).getIntervalSeconds());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> IntervalSecondsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", IntervalSecondsVO.from(1).toString());
  }
}
